def is_type_b(N):
    f = [0] * (N + 1)
    # f[n] = 1 if the player whose turn it is to move from n can win
    # The game ends when a player writes N.
    # The player who is at position n wins if they can move to N,
    # or if they can move to a position m such that f[m] = 0.
    for n in range(N - 1, 0, -1):
        # Possible moves from n: n+1 and 2*n
        # If move to N is possible, f[n] = 1
        if n + 1 == N or (2 * n == N):
            f[n] = 1
        else:
            # Otherwise, check if they can move to a position where the other player loses
            can_move_to_losing = False
            # move to n+1
            if n + 1 < N and f[n+1] == 0:
                can_move_to_losing = True
            # move to 2*n
            if 2 * n < N and f[2*n] == 0:
                can_move_to_losing = True

            if can_move_to_losing:
                f[n] = 1
            else:
                f[n] = 0
    return f[1] == 1

